def best_shift_orf(ss, atg, maxcodons=4000):
    """Walk from atg; consider a single shift at each codon boundary before first stop.
       Return list of (total_len, shift_pos, delta, protein)."""
    out=[]
    pos=atg; prot=[]
    while pos+3<=len(ss):
        aa=codon.get(ss[pos:pos+3],"X")
        if aa=="*": break
        # option: shift here, before translating codon at pos
        for delta in (-1,1):
            ns=pos+delta
            p2=[];q=ns
            while q+3<=len(ss):
                a2=codon.get(ss[q:q+3],"X")
                if a2=="*": break
                p2.append(a2); q+=3
            out.append((len(prot)+len(p2), pos, delta, "".join(prot)+"|"+"".join(p2)))
        prot.append(aa); pos+=3
    out.append((len(prot),None,0,"".join(prot)))
    return out

